*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:            #0f1117;
  --surface:       #1a1d27;
  --surface-hover: #222636;
  --border:        #2e3248;
  --border-focus:  #6c8aff;
  --accent:        #6c8aff;
  --accent-dark:   #4a68e8;
  --text:          #e2e4f0;
  --text-muted:    #8b90aa;
  --text-error:    #ff7b7b;
  --success:       #4caf88;
  --radius:        10px;
  --transition:    160ms ease;
}

/* ── Skip link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 600;
  z-index: 999;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Page ───────────────────────────────────────────────────── */
body {
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2.5rem 1rem 4rem;
  line-height: 1.6;
}

/* ── Header ─────────────────────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2.5rem;
  max-width: 640px;
  width: 100%;
}
.page-header h1 {
  font-size: clamp(1.6rem, 4vw, 2.4rem);
  font-weight: 700;
  letter-spacing: -.02em;
  background: linear-gradient(135deg, #a0b4ff 0%, #c792ea 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.page-header p {
  margin-top: .5rem;
  color: var(--text-muted);
  font-size: .95rem;
}

/* ── Form ───────────────────────────────────────────────────── */
.quiz-form {
  width: 100%;
  max-width: 640px;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* ── Question card (form-field) ─────────────────────────────── */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem 1.75rem;
  transition: border-color var(--transition);
}
.form-field:focus-within { border-color: var(--border-focus); }
.form-field.has-error     { border-color: var(--text-error); }

/* ── Fieldset / legend ──────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}
legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  line-height: 1.4;
  margin-bottom: .5rem;
  float: left;  /* keeps legend inside the fieldset box */
  width: 100%;
}
/* clear the float so subsequent children stack normally */
legend + * { clear: both; }

.question-number {
  display: inline-block;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: .35rem;
}

/* ── Help / error text ──────────────────────────────────────── */
.help-text {
  font-size: .83rem;
  color: var(--text-muted);
  margin-top: -.1rem;
  margin-bottom: .9rem;
}
.error-text {
  font-size: .83rem;
  color: var(--text-error);
  margin-top: .6rem;
  display: flex;
  align-items: center;
  gap: .35rem;
}
.error-text::before {
  content: "⚠";
  font-size: .9em;
  flex-shrink: 0;
}
[hidden] { display: none !important; }

/* ── Checkbox options ───────────────────────────────────────── */
.options {
  display: flex;
  flex-direction: column;
  gap: .45rem;
  margin-top: .25rem;
}
.option-label {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .6rem .85rem;
  border-radius: calc(var(--radius) - 2px);
  border: 1px solid var(--border);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  user-select: none;
}
.option-label:hover {
  background: var(--surface-hover);
  border-color: var(--accent);
}

/* native checkbox — visually hidden but still in the tab order */
.option-label input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.15rem;
  height: 1.15rem;
  border: 2px solid var(--border);
  border-radius: 4px;
  background: transparent;
  cursor: pointer;
  position: relative;
  transition: border-color var(--transition), background var(--transition);
}
.option-label input[type="checkbox"]:checked {
  background: var(--accent);
  border-color: var(--accent);
}
.option-label input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  inset: 2px 1px 2px 3px;
  border: 2px solid #fff;
  border-top: none;
  border-right: none;
  transform: rotate(-45deg) translateY(-1px);
}
.option-label input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}
.option-label:has(input:checked) {
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
  border-color: var(--accent);
  color: #fff;
}

/* ── Submit button ──────────────────────────────────────────── */
.submit-btn {
  align-self: flex-end;
  padding: .7rem 2rem;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), transform 80ms ease;
}
.submit-btn:hover  { background: var(--accent-dark); }
.submit-btn:active { transform: scale(.97); }
.submit-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
}

/* ── Results banner ─────────────────────────────────────────── */
.results-banner {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem 1.75rem;
  text-align: center;
}
.results-banner h2 {
  font-size: 1.3rem;
  margin-bottom: .4rem;
}
.score-value {
  font-size: 2.8rem;
  font-weight: 800;
  color: var(--accent);
  line-height: 1.1;
}
.results-banner p { color: var(--text-muted); margin-top: .5rem; font-size: .9rem; }

/* correct / incorrect answer highlighting */
.option-label.correct  { border-color: var(--success) !important; background: color-mix(in srgb, var(--success) 15%, var(--surface)) !important; }
.option-label.wrong    { border-color: var(--text-error) !important; background: color-mix(in srgb, var(--text-error) 12%, var(--surface)) !important; }

/* ── Forced-colors (high-contrast) override ─────────────────── */
@media (forced-colors: active) {
  .option-label input[type="checkbox"]:checked { forced-color-adjust: none; }
  .submit-btn { forced-color-adjust: none; }
}

/* ── Reduced motion ─────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0ms !important; }
}

/* ── Reflow (320 px) ────────────────────────────────────────── */
@media (max-width: 360px) {
  .form-field { padding: 1.1rem 1rem; }
  .submit-btn { align-self: stretch; }
}
