AssistantMessageToolRequest(name='create', tool_call_id='tooluse_fGxmZHkIdhpoKB9At1IYWT', arguments={'file_text': '(() => {
  "use strict";

  /* ── Quiz data ───────────────────────────────────────────────
     Each question lists which answer *indices* (0-based) are correct.
  ──────────────────────────────────────────────────────────── */
  const questions = [
    {
      id: "q1",
      text: "Which of the following are statically-typed languages?",
      helpId: "q1-help",
      helpText: "Select all that apply. There may be more than one correct answer.",
      answers: ["TypeScript", "Python", "Java", "Go"],
      correct: new Set([0, 2, 3]),
    },
    {
      id: "q2",
      text: "Which languages are primarily used for web front-end development?",
      answers: ["JavaScript", "CSS", "Rust", "HTML"],
      correct: new Set([0, 1, 3]),
    },
    {
      id: "q3",
      text: "Which of the following languages feature automatic garbage collection?",
      answers: ["C", "Python", "Java", "C++"],
      correct: new Set([1, 2]),
    },
  ];

  /* ── Helpers ─────────────────────────────────────────────── */
  const qs  = (sel, ctx = document) => ctx.querySelector(sel);
  const qsa = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];

  /* ── Validate one fieldset — returns true if OK ─────────── */
  function validateGroup(fieldset, errorEl) {
    const checked = qsa("input[type=checkbox]:checked", fieldset);
    if (checked.length === 0) {
      errorEl.hidden = false;
      fieldset.setAttribute("aria-describedby",
        (fieldset.getAttribute("aria-describedby") || "")
          .split(" ")
          .filter(Boolean)
          .concat(errorEl.id)
          .join(" ")
      );
      return false;
    }
    errorEl.hidden = true;
    return true;
  }

  /* ── Build UI ────────────────────────────────────────────── */
  function buildQuiz() {
    const form = qs("#quiz-form");
    const statusEl = qs("#status-msg");

    questions.forEach((q, qi) => {
      /* wrapper card */
      const card = document.createElement("div");
      card.className = "form-field";

      /* fieldset */
      const fieldset = document.createElement("fieldset");
      const describedBy = [];

      if (q.helpId) describedBy.push(q.helpId);
      const errorId = `${q.id}-error`;
      describedBy.push(errorId);
      fieldset.setAttribute("aria-describedby", describedBy.join(" "));

      /* legend */
      const legend = document.createElement("legend");
      const numSpan = document.createElement("span");
      numSpan.className = "question-number";
      numSpan.textContent = `Question ${qi + 1} of ${questions.length}`;
      legend.appendChild(numSpan);
      legend.appendChild(document.createElement("br"));
      legend.appendChild(document.createTextNode(q.text));
      fieldset.appendChild(legend);

      /* optional help text */
      if (q.helpId) {
        const help = document.createElement("p");
        help.id = q.helpId;
        help.className = "help-text";
        help.textContent = q.helpText;
        fieldset.appendChild(help);
      }

      /* answer options */
      const optionsDiv = document.createElement("div");
      optionsDiv.className = "options";
      q.answers.forEach((answer, ai) => {
        const inputId = `${q.id}-a${ai}`;
        const label = document.createElement("label");
        label.className = "option-label";
        label.htmlFor = inputId;

        const cb = document.createElement("input");
        cb.type = "checkbox";
        cb.id = inputId;
        cb.name = q.id;
        cb.value = String(ai);

        label.appendChild(cb);
        label.appendChild(document.createTextNode(answer));
        optionsDiv.appendChild(label);
      });
      fieldset.appendChild(optionsDiv);

      /* error message (hidden by default) */
      const errorEl = document.createElement("p");
      errorEl.id = errorId;
      errorEl.className = "error-text";
      errorEl.setAttribute("role", "alert");
      errorEl.hidden = true;
      errorEl.textContent = "Error: Please select at least one answer.";
      fieldset.appendChild(errorEl);

      card.appendChild(fieldset);
      form.insertBefore(card, qs("#form-footer", form));
    });
  }

  /* ── Score & reveal answers ──────────────────────────────── */
  function scoreAndReveal() {
    let correctCount = 0;

    questions.forEach((q) => {
      const fieldset = qs(`[name="${q.id}"]`)?.closest("fieldset");
      if (!fieldset) return;

      const allCbs = qsa(`input[name="${q.id}"]`);
      const selected = new Set(
        allCbs.filter((cb) => cb.checked).map((cb) => Number(cb.value))
      );

      /* check if selection exactly matches correct set */
      const isCorrect =
        selected.size === q.correct.size &&
        [...selected].every((v) => q.correct.has(v));
      if (isCorrect) correctCount++;

      /* highlight each option */
      allCbs.forEach((cb) => {
        const idx = Number(cb.value);
        const label = cb.closest(".option-label");
        cb.disabled = true;
        if (q.correct.has(idx) && cb.checked)  { label.classList.add("correct"); }
        else if (!q.correct.has(idx) && cb.checked) { label.classList.add("wrong"); }
        else if (q.correct.has(idx) && !cb.checked) { label.classList.add("correct"); }
      });
    });

    return correctCount;
  }

  /* ── Submit handler ──────────────────────────────────────── */
  function handleSubmit(e) {
    e.preventDefault();
    const form = e.target;
    const statusEl = qs("#status-msg");

    /* validate all groups */
    let firstInvalidFieldset = null;
    let allValid = true;

    questions.forEach((q) => {
      const fieldset = qs(`[name="${q.id}"]`)?.closest("fieldset");
      const errorEl  = qs(`#${q.id}-error`);
      if (!fieldset || !errorEl) return;

      const card = fieldset.closest(".form-field");
      const valid = validateGroup(fieldset, errorEl);
      if (!valid) {
        card.classList.add("has-error");
        allValid = false;
        if (!firstInvalidFieldset) firstInvalidFieldset = fieldset;
      } else {
        card.classList.remove("has-error");
      }
    });

    if (!allValid) {
      /* move focus to first unanswered question's first checkbox */
      const firstCb = qs("input[type=checkbox]", firstInvalidFieldset);
      firstCb?.focus();
      statusEl.textContent = "Please answer all questions before submitting.";
      return;
    }

    /* all good — score */
    const score = scoreAndReveal();
    const total = questions.length;

    /* hide submit, show results */
    qs("#submit-btn").hidden = true;
    const banner = qs("#results-banner");
    banner.hidden = false;
    qs("#score-value").textContent = `${score} / ${total}`;
    qs("#score-label").textContent =
      score === total ? "Perfect score! 🎉" :
      score >= total / 2 ? "Nice work! Keep it up 👍" :
      "Keep studying — you've got this! 📚";

    /* live region announcement */
    statusEl.textContent = `Quiz submitted. You scored ${score} out of ${total}.`;
    banner.focus();
  }

  /* ── Init ────────────────────────────────────────────────── */
  document.addEventListener("DOMContentLoaded", () => {
    buildQuiz();
    qs("#quiz-form").addEventListener("submit", handleSubmit);

    /* clear card error state when user interacts with a question */
    document.addEventListener("change", (e) => {
      if (e.target.type !== "checkbox") return;
      const card = e.target.closest(".form-field");
      const fieldset = e.target.closest("fieldset");
      const errorEl = fieldset && qs(`#${fieldset.querySelector("input")?.name}-error`, fieldset.closest(".form-field"));
      if (card) card.classList.remove("has-error");
      if (errorEl) errorEl.hidden = true;
    });
  });
})();
