const { chromium } = require("playwright");
const fs = require("fs");
const path = require("path");

(async () => {
  const html = fs.readFileSync("index.html", "utf8");
  const css  = fs.readFileSync("styles.css",  "utf8");
  const js   = fs.readFileSync("quiz.js",     "utf8");

  // Inline all assets so the browser sees a complete page with no file:// cross-origin issues
  const inlined = html
    .replace('<link rel="stylesheet" href="styles.css">', `<style>${css}</style>`)
    .replace('<script src="quiz.js"></script>', `<script>${js}</script>`);

  const browser = await chromium.launch();
  const page    = await browser.newPage();
  await page.setContent(inlined, { waitUntil: "load" });
  await page.addScriptTag({ path: "/tmp/axe.min.js" });

  const results = await page.evaluate(async () => await window.axe.run());
  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes("best-practice"));
  const bp   = results.violations.filter(v =>  v.tags.includes("best-practice"));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description, targets: v.nodes.map(n => n.target) })),
    bp:   bp.map  (v => ({ id: v.id, impact: v.impact, description: v.description, targets: v.nodes.map(n => n.target) })),
  }, null, 2));

  process.exit(wcag.length ? 1 : 0);
})();
EOF
