  flex-direction: column;
  gap: .45rem;
  margin-top: .25rem;
}
.option-label {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .6rem .85rem;
  border-radius: calc(var(--radius) - 2px);
